def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_c = 0
    for h in history:
        if h[1] == 'C':
            opp_c += 1
    opp_d = n - opp_c
    opp_c_rate = opp_c / n

    if opp_c_rate < 0.3:
        return 'D'

    last_me, last_opp = history[-1]

    if last_opp == 'D':
        recent_my_d = False
        if n >= 1 and history[-1][0] == 'D':
            recent_my_d = True
        if n >= 2 and history[-2][0] == 'D':
            recent_my_d = True
        if recent_my_d:
            return 'C'
        else:
            if opp_c_rate > 0.8 and rng.random() < 0.15:
                return 'C'
            return 'D'

    if n >= 1 and history[-1][0] == 'D':
        return 'C'
    if n >= 2 and history[-2][0] == 'D':
        return 'C'

    dc_count = 0
    retaliate_count = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C':
            dc_count += 1
            if history[i+1][1] == 'D':
                retaliate_count += 1

    if dc_count >= 3:
        r = retaliate_count / dc_count
    else:
        r = 0.5

    if n >= 95:
        if dc_count >= 3 and r < 0.5:
            p_defect = 0.8
        else:
            p_defect = 0.0
    else:
        if dc_count >= 3:
            p_defect = max(0.0, min(0.5, 0.5 - r))
        else:
            if n < 20:
                p_defect = 0.0
            else:
                p_defect = 0.05

    if rng.random() < p_defect:
        return 'D'
    return 'C'
